package com.ryanjei.orushio.pve.application;
import com.ryanjei.orushio.pve.core.*;import com.ryanjei.orushio.pve.domain.GameLaunchSettings;import com.ryanjei.orushio.pve.economy.*;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.pve.*;import java.util.*;
public final class Phase4GameReadinessValidator implements GameReadinessValidator{
 private final GameplaySettingsRepository gameplay;private final PveSettingsRepository pve;private final CoreSettingsRepository cores;private final ResourceMaterialValidator materials;
 public Phase4GameReadinessValidator(GameplaySettingsRepository gameplay,PveSettingsRepository pve,CoreSettingsRepository cores,ResourceMaterialValidator materials){this.gameplay=gameplay;this.pve=pve;this.cores=cores;this.materials=materials;}
 public List<String>missing(MapProfile map,GameLaunchSettings launch){LinkedHashSet<String>missing=new LinkedHashSet<>();long initial=map.enabledSetupMarkers(SetupMarkerType.INITIAL_RESPAWN).size();for(String key:map.missingRequirements()){if(key.equals("marker:INITIAL_RESPAWN")&&initial>1)continue;missing.add(label(key)+"の設定がありません。");}if(initial>1)missing.add("初期リスポーン地点が1件だけ有効になっていません。");if(map.areas().getOrDefault("resourceZones",List.of()).isEmpty())missing.add("資源採取エリアの設定がありません。");try{GameplaySettings value=gameplay.load(map.mapId().value());try{FarmEconomyLifecycleStep.validateConfiguration(map,value,materials);}catch(RuntimeException failure){if(map.areas().getOrDefault("resourceZones",List.of()).stream().anyMatch(region->value.resourceZones().stream().noneMatch(zone->zone.region().equals(region))))missing.add("資源採取エリアのPoint・再生成設定がありません。");if(missing.stream().noneMatch(text->text.contains("資源採取")||text.contains("ショップ")))missing.add("資源・ショップ設定に不整合があります。");}}catch(RuntimeException failure){missing.add("資源・ショップ設定を読み込めません。");}try{PveSettings value=pve.load(map.mapId().value());List<Cuboid>areas=map.areas().getOrDefault("enemyZones",List.of());for(int i=0;i<areas.size();i++){Cuboid area=areas.get(i);if(value.enemyZones().stream().noneMatch(zone->zone.region().equals(area)))missing.add("Enemy Zone "+(i+1)+" の敵・出現間隔設定がありません。");}try{PveLifecycleStep.validateConfiguration(map,value);}catch(RuntimeException failure){if(missing.stream().noneMatch(text->text.startsWith("Enemy Zone")))missing.add("敵出現設定に不整合があります。");}}catch(RuntimeException failure){missing.add("敵出現設定を読み込めません。");}try{cores.load(map.mapId().value());}catch(RuntimeException failure){missing.add("通常コア・最終コアのHP設定がありません。");}if(map.enabledSetupMarkers(SetupMarkerType.NORMAL_CORE).size()<launch.resolvedRequiredNormalCores())missing.add("攻略に必要な有効な通常コア候補地点が不足しています。");return List.copyOf(missing);}
 private static String label(String key){if(key.startsWith("marker:")){try{return SetupMarkerType.valueOf(key.substring(7)).label();}catch(RuntimeException ignored){return "設定地点";}}try{return MapFieldCatalog.label(key);}catch(RuntimeException ignored){return "マップ必須項目";}}
}
